<?php
require_once __DIR__.'/production.php';
$id=(int)($_GET['id']??0);$plan=$id?query('SELECT * FROM production_plans WHERE id=?',[$id])->fetch():false;
if($id&&!$plan){http_response_code(404);echo '<p>생산 계획을 찾을 수 없습니다.</p>';return;}
?>
<div class="toolbar no-print"><a class="button secondary" href="/?page=production-settings">주재료·배합 기준 관리</a><?php if($plan): ?><a class="button secondary" href="/?page=production">새 생산 계획</a><button class="button" id="print-order">생산 계획 인쇄</button><?php endif ?></div>
<?php if($plan): $s=json_decode($plan['snapshot'],true,512,JSON_THROW_ON_ERROR); ?>
<div class="production-print"><h2><?=e($plan['title'])?> · <?=e($plan['plan_date'])?></h2><p class="hint">계획 #<?=(int)$plan['id']?> · 주문 <?=count($s['orders'])?>건 · 배합 기준은 저장 당시 기준 · 표시량은 1g 단위 반올림</p>
<?php if($s['warnings']): ?><div class="alert error">계산 제외: <?=e(implode(' / ',$s['warnings']))?>. 기준을 보완한 뒤 새 계획을 만드세요.</div><?php endif ?>
<h3>생산 계획표</h3><div class="table-wrap"><table><thead><tr><th>구분</th><th>제품 / 용량</th><th>수량</th><th>생산량</th><th>배추</th><th>무우</th><th>절임소금</th><th>다른 주재료 / 확인</th></tr></thead><tbody>
<?php foreach($s['rows'] as $r): ?><tr><td><?=e($r['channel'])?></td><td><?=e($r['name'])?> <small><?=weight($r['weight_g'])?></small></td><td><?=(int)$r['quantity']?>개</td><td><?=productionKg($r['grams'])?></td><?php foreach(['배추','무우','절임소금'] as $m): ?><td><?=isset($r['materials'][$m])?productionKg($r['materials'][$m]):'—'?></td><?php endforeach ?><td><?php if(!$r['materials']): ?>기준 확인 필요<?php else: foreach(array_diff_key($r['materials'],array_flip(['배추','무우','절임소금'])) as $m=>$g): ?><?=e($m)?> <?=productionKg($g)?> <?php endforeach;endif ?></td></tr><?php endforeach ?>
</tbody></table></div>
<p class="production-totals"><strong>전체 주재료 합계</strong> <?php foreach($s['totals'] as $m=>$g): ?><span><?=e($m)?> <strong><?=productionKg($g)?></strong></span> <?php endforeach ?></p>
<h3>배추 절임계획</h3><div class="table-wrap"><table><thead><tr><th>절임 그룹</th><th>배추</th><th>무우</th><th>절임소금</th></tr></thead><tbody><?php foreach(['pogi'=>'포기김치 그룹','mat'=>'맛김치 그룹'] as $key=>$label): ?><tr><th><?=$label?></th><?php foreach(['배추','무우','절임소금'] as $m): ?><td><?=productionKg($s['groups'][$key][$m])?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div>
<p class="hint">포기 그룹: 포기·백포기·겉절이 / 맛 그룹: 맛·물·순한맛·비건·백김치. 주문분과 마트분을 합산합니다. 소금은 각 제품의 배추량과 배합률로 계산한 뒤 합산합니다. 동치미·깍두기·파김치는 위 전체 주재료 합계에만 포함됩니다.</p>
<?php if($s['warnings']): ?><p class="production-warning">※ 미계산 제품이 있습니다: <?=e(implode(' / ',$s['warnings']))?></p><?php endif ?>
</div><details class="panel no-print"><summary>선택한 주문 확인 · <?=count($s['orders'])?>건</summary><?php foreach($s['orders'] as $o): ?><p><a href="/?page=order&id=<?=(int)$o['id']?>">#<?=(int)$o['id']?> <?=e($o['name'])?></a> · 대기 <?=(int)$o['pending']?>개</p><?php endforeach ?></details>
<?php else:
$orders=query('SELECT o.*,SUM(i.quantity-i.cancelled_quantity-i.delivered_quantity) remaining FROM orders o JOIN order_items i ON i.order_id=o.id WHERE o.cancelled=0 GROUP BY o.id HAVING remaining>0 ORDER BY o.delivery_date IS NULL,o.delivery_date,o.id')->fetchAll();$retail=query('SELECT * FROM production_retail WHERE active=1 ORDER BY id')->fetchAll();
?>
<p class="notice">미전달 수량만 계산합니다. 선입금 주문도 포함됩니다. 계획을 저장해도 주문의 전달·입금 상태는 바뀌지 않습니다. 같은 주문으로 여러 계획을 만들 수 있으니 중복 생산에 유의하세요.</p>
<form method="post" class="stack" id="production-form"><?=csrf()?><input type="hidden" name="action" value="production_save"><input type="hidden" name="request_key" value="<?=e(pv('request_key',bin2hex(random_bytes(16))))?>"><section class="panel form-grid"><label>생산 날짜<input type="date" name="plan_date" value="<?=e(pv('plan_date',date('Y-m-d')))?>" required></label><label>계획 이름<input name="title" maxlength="100" value="<?=e(pv('title','김치 생산 계획'))?>" required></label></section>
<section class="panel"><div class="section-title"><h2>1. 생산할 주문 선택 · <?=count($orders)?>건</h2><div class="actions"><button type="button" class="button secondary" data-production-select="all">모두 선택</button><button type="button" class="button secondary" data-production-select="none">선택 해제</button><span id="production-count" aria-live="polite">0건 선택</span></div></div>
<div class="table-wrap"><table><thead><tr><th>선택</th><th>주문 / 고객</th><th>받을 날짜</th><th>미전달 제품</th><th>대기 수량</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><input class="production-check" type="checkbox" name="orders[]" value="<?=(int)$o['id']?>" aria-label="<?=e('#'.$o['id'].' '.$o['customer_name'].' 선택')?>" <?=in_array((string)$o['id'],$_POST['orders']??[],true)?'checked':''?>></td><td><a href="/?page=order&id=<?=(int)$o['id']?>">#<?=(int)$o['id']?> <?=e($o['customer_name'])?></a></td><td><?=e($o['delivery_date']??'미기록')?></td><td><?php foreach(orderItems((int)$o['id']) as $i): if(!pendingQty($i))continue; ?><small><?=e($i['product_name'])?> <?=weight($i['weight_g'])?> × <?=pendingQty($i)?></small><?php endforeach ?></td><td><?=(int)$o['remaining']?>개</td></tr><?php endforeach ?></tbody></table></div><?php if(!$orders): ?><p>미전달 주문이 없습니다. 마트분만으로도 계획을 만들 수 있습니다.</p><?php endif ?></section>
<section class="panel"><h2>2. 마트판매분 수량 입력</h2><p class="hint">김치방 주문 목록과 분리된 생산 전용 제품입니다. 개수를 입력하면 무게로 환산합니다.</p><div class="production-retail-grid"><?php foreach($retail as $p): ?><label><?=e($p['name'])?> · <?=weight($p['weight_g'])?><input type="number" name="retail[<?=(int)$p['id']?>]" value="<?=e((string)($_POST['retail'][$p['id']]??0))?>" min="0" max="100000" step="1" data-pack-grams="<?=(int)$p['weight_g']?>"><small class="pack-total">0 kg</small></label><?php endforeach ?></div></section>
<button class="button large">생산 계획 저장·계산하기</button></form>
<section class="panel minor-action"><h2>저장한 생산 계획</h2><?php foreach(query('SELECT id,title,plan_date FROM production_plans ORDER BY id DESC LIMIT 50')->fetchAll() as $p): ?><p><a href="/?page=production&id=<?=(int)$p['id']?>"><?=e($p['plan_date'].' · '.$p['title'])?> #<?=(int)$p['id']?></a></p><?php endforeach ?><p class="hint">최근 50건을 표시합니다. 저장한 계획은 당시 수량과 배합을 보존하며, 이후 주문 변경이나 배송 상태가 자동 반영되지 않습니다.</p></section>
